  document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const handled=['signin','register','logout','wallet','event-checkout','save'].includes(b.dataset.action)||b.dataset.action.startsWith('a-');if(!handled||(b.dataset.action==='save'&&role()==='buyer'))return;ev.preventDefault();ev.stopImmediatePropagation();if(!nftRunning)run(()=>action(b.dataset.action,b))},true);
